import re as _re
_D = str.maketrans("0123456789", "۰۱۲۳۴۵۶۷۸۹")
def fa(x):
    """ارقام لاتینِ مستقل را فارسی می‌کند؛ شناسه‌ها (v5.3، S9، p95، B8، CKD-EPI 2021 …) و متن داخل پرانتزهای فنی دست‌نخورده می‌مانند."""
    def rep(m):
        tok = m.group(0)
        if "." in tok and _re.fullmatch(r"\d+\.\d+", tok):
            return tok.translate(_D).replace(".", "٫")
        return tok.translate(_D)
    # عدد (با اعشار اختیاری) که به حرف لاتین/خط‌تیره/اسلش چسبیده نباشد
    out = _re.sub(r"(?<![A-Za-z0-9_./\-])\d+(?:\.\d+)?(?![A-Za-z0-9_./\-])", rep, str(x))
    out = _re.sub(r"([۰-۹])%", r"\1٪", out)
    return out

